App.my.KEY = 'tasks';
App.my.open = () => App.items(App.my.KEY).filter((t) => !t.done)
  .sort((a, b) => ((a.date || '9999') + (a.time || '')).localeCompare((b.date || '9999') + (b.time || '')) || a.at - b.at);
App.my.done = () => App.items(App.my.KEY).filter((t) => t.done).sort((a, b) => (b.doneAt || 0) - (a.doneAt || 0));
App.my.when = (t) => [t.date ? App.date(t.date, 'short') : '', t.time || ''].filter(Boolean).join(' ');
App.my.widget = async () => {
  const o = App.my.open();
  const lines = o.length ? o.slice(0, 3).map((t) => '• ' + t.title + (t.date ? ' (' + App.date(t.date, 'short') + ')' : '')) : ['అన్ని పనులు అయిపోయాయి 🎉'];
  try { await App.widget('✅ పనులు: ' + o.length, lines); } catch (e) { /* the widget only helps */ }
};
/** A reminder at the task's date and time (only when he asked, both are set and it is still to come): true when set. */
App.my.remind = async (t) => {
  try { await App.unremind(t.id); } catch (e) { /* */ }
  if (!t || t.done || !t.remind || !t.date || !t.time) return false;
  try {
    await App.remind({ id: t.id, when: t.date + ' ' + t.time, title: '✅ ' + t.title, text: 'ఈ పని సమయం అయింది', screen: 'home' });
    return true;
  } catch (e) { return false; }
};
App.my.save = async (rec, id) => {
  let t;
  if (id) { App.update(App.my.KEY, id, rec); t = App.find(App.my.KEY, id); } else t = App.add(App.my.KEY, rec);
  const rem = await App.my.remind(t);
  App.my.widget();
  return { t, rem };
};
App.my.hhmm = (s) => { const m = /^(\d{1,2}):(\d{2})$/.exec(String(s || '').trim()); return m && +m[1] < 24 && +m[2] < 60 ? (m[1].length < 2 ? '0' : '') + m[1] + ':' + m[2] : ''; };
App.onStart(() => { App.my.widget(); });
App.onJarvis('add', async (d) => {
  const title = String(d.title || '').trim().slice(0, 100);
  if (!title) return 'పని పేరు లేదు; ఏమీ రాయలేదు';
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(d.date || '')) ? d.date : '', time = App.my.hhmm(d.time);
  const { t, rem } = await App.my.save({ title, date, time, remind: !!(date && time), note: '', done: false });
  return '"' + title + '" రాశాను' + (rem ? ', ' + App.my.when(t) + ' కి గుర్తు చేస్తాను' : '');
});

App.my.row = (t) => {
  const late = !t.done && t.date && t.date < App.today();
  return `<div class="item ${t.done ? 'done' : ''}" data-id="${App.esc(t.id)}">
    <button class="ic tick" data-id="${App.esc(t.id)}" aria-label="అయింది">${t.done ? '✅' : '⬜'}</button>
    <div class="w"><div class="t">${App.esc(t.title)}</div>
      <div class="s ${late ? 'late' : ''}">${App.esc(App.my.when(t) || 'తేదీ లేదు')}${t.remind && !t.done ? ' · 🔔' : ''}${late ? ' · ఆలస్యం' : ''}</div></div>
  </div>`;
};
App.onShow('home', () => {
  const o = App.my.open();
  App.text('#home-count', o.length ? o.length + ' పనులు మిగిలాయి' : 'అన్ని పనులు అయిపోయాయి 🎉');
  App.set('#home-list', o.length ? '<div class="list">' + o.map(App.my.row).join('') + '</div>'
    : '<div class="empty"><div class="e">✅</div>చేయాల్సిన పనులు లేవు. + నొక్కి రాయండి.<div class="faint">Jarvis తో: "పనుల లిస్ట్‌లో రేపు 10 కి బ్యాంక్ పని రాయి"</div></div>');
});
App.click('#home-add', () => App.go('add'));
App.click('.tick', async (ev, el) => {
  const t = App.find(App.my.KEY, el.dataset.id);
  if (!t) return;
  await App.my.save({ done: !t.done, doneAt: t.done ? 0 : Date.now() }, t.id);
  App.beep(t.done ? 'tap' : 'done');
  App.toast(t.done ? 'మళ్ళీ చేయాల్సినవాటిలో పెట్టాను' : 'బాగుంది Sir, అయింది ✅');
  App.refresh();
});
App.click('#home-list .item', (ev, el) => { if (ev.target.closest('.tick')) return; App.go('add', App.find(App.my.KEY, el.dataset.id)); });
App.click('#home-say', async () => {
  const o = App.my.open();
  try { await App.say(o.length ? o.length + ' పనులు ఉన్నాయి. ' + o.slice(0, 5).map((t) => t.title).join('. ') : 'చేయాల్సిన పనులు ఏమీ లేవు'); }
  catch (e) { App.toast('చదవలేకపోయాను'); }
});
App.action('home', '📤', async () => {
  const o = App.my.open();
  const text = '✅ పనులు:\n' + (o.length ? o.map((t) => '• ' + t.title + (t.date ? ' (' + App.my.when(t) + ')' : '')).join('\n') : 'ఏమీ లేవు');
  try { await App.share(text); } catch (e) { App.toast('షేర్ కాలేదు'); }
}, 'షేర్');

App.onShow('add', (t) => {
  App.my.editing = t && t.id ? t.id : null;
  App.title(App.my.editing ? 'పని మార్చండి' : 'కొత్త పని');
  App.val('#add-title', t && t.title ? t.title : '');
  App.val('#add-date', t ? t.date || '' : App.today());
  App.val('#add-time', t && t.time ? t.time : '');
  App.val('#add-rem', t ? !!t.remind : true);
  App.val('#add-note', t && t.note ? t.note : '');
  App.show('#add-del', !!App.my.editing);
});
App.click('#add-mic', async () => {
  try { const s = await App.listen('ఏ పని?'); if (s) App.val('#add-title', s.slice(0, 100)); } catch (e) { App.toast('మాట వినలేకపోయాను'); }
});
App.click('#add-save', async () => {
  const title = App.val('#add-title');
  if (!title) { App.toast('పని ఏమిటో రాయండి'); return; }
  const rec = { title: title.slice(0, 100), date: App.val('#add-date'), time: App.my.hhmm(App.val('#add-time')), remind: App.val('#add-rem') === true, note: App.val('#add-note').slice(0, 500) };
  if (!App.my.editing) rec.done = false;
  const { rem } = await App.my.save(rec, App.my.editing);
  App.beep('ok');
  App.toast(rec.remind && !rem ? 'దాచాను (తేదీ, సమయం లేవు / దాటిపోయింది: రిమైండర్ పెట్టలేదు)' : rem ? 'దాచాను, 🔔 గుర్తు చేస్తాను' : 'దాచాను', 3);
  App.back();
});
App.click('#add-del', async () => {
  if (!App.my.editing) return;
  if (await App.ask('ఈ పని తీసేయాలా?', 'తీసేయి', 'వద్దు')) {
    try { await App.unremind(App.my.editing); } catch (e) { /* */ }
    App.del(App.my.KEY, App.my.editing); App.my.widget(); App.toast('తీసేశాను'); App.back();
  }
});

App.onShow('done', () => {
  const d = App.my.done();
  App.set('#done-list', d.length ? '<div class="list">' + d.slice(0, 100).map(App.my.row).join('') + '</div>'
    : '<div class="empty"><div class="e">🗂️</div>అయిన పనులు ఇక్కడ కనిపిస్తాయి.</div>');
});
App.action('done', '🗑️', async () => {
  const d = App.my.done();
  if (!d.length) { App.toast('తీసేయడానికి ఏమీ లేవు'); return; }
  if (await App.ask(d.length + ' అయిన పనులు తీసేయాలా?', 'తీసేయి', 'వద్దు')) { for (const t of d) App.del(App.my.KEY, t.id); App.toast('తీసేశాను'); App.refresh(); }
}, 'అయినవి తీసేయి');
